#!/usr/bin/env python3
"""Applies manual fixes to the Java tests generated by rb2java.rb.

The generated tests sometimes need adjustments that cannot be inferred by the translator (casts, Ruby-only
features). The fixes are stored in this file so the tests can be regenerated when the Ruby test suite changes.

Usage: tools/fix_tests.py TestName...
"""
import re
import sys
import textwrap
from pathlib import Path

PROJECT_DIR = Path(__file__).resolve().parent.parent
# the CLI tests are located in the asciidoctorj-cli module, the other tests in the asciidoctorj-core module
CLI_TESTS = {'InvokerTest', 'OptionsTest'}


def test_dir(test):
    module = 'asciidoctorj-cli' if test in CLI_TESTS else 'asciidoctorj-core'
    return PROJECT_DIR / module / 'src/test/java/org/asciidoctor/core'

# test class -> list of (old, new) literal replacements (old may be a compiled regex)
REPLACEMENTS = {}
# test class -> list of (display name, reason)
DISABLED = {}
# test class -> list of (display name, Java body)
REWRITTEN = {}
# test class -> list of additional imports
IMPORTS = {}
# test class -> list of (context name, reason)
DISABLED_CONTEXTS = {}
# test class -> list of members (Java code) to add to the test class
MEMBERS = {}

# replacements applied to all the tests (if they match)
COMMON_REPLACEMENTS = [
    # the value of an attribute is not typed
    (re.compile(r'Strings\.(strip|rstrip|lstrip|chomp)\((\w+\.getAttribute\([^()]*\))\)'), r'Strings.\1(str(\2))'),
    # the tests are run from the asciidoctorj-core module, where the fixtures are located in src/test/resources
    ('"test/', '"src/test/resources/'),
    # Java strings are always Unicode
    (re.compile(r'\n[ \t]*assertEquals\([^\n]*Encoding\.UTF_8\);'), ''),
    # the asciimath gem is not available (AsciiMath is not supported by the Java implementation)
    ('!((Helpers.requireLibrary("asciimath", true, "ignore") == null))', 'false'),
    (re.compile(r'\n[ \t]*[^\n]*(?:asciimathStatus|instanceVariableGet\("@asciimath_status"\))[^\n]*;'), ''),
    (re.compile(r'\n[ \t]*(?:var oldAsciimath = AsciiMath|Object\.send\("remove_const", "AsciiMath"\)|Object\.constSet\("AsciiMath", oldAsciimath\));'), ''),
]


def replace(test, *pairs):
    REPLACEMENTS.setdefault(test, []).extend(zip(pairs[::2], pairs[1::2]))


def disable(test, reason, *names):
    DISABLED.setdefault(test, []).extend((name, reason) for name in names)


def add_members(test, code):
    MEMBERS.setdefault(test, []).append(textwrap.dedent(code).strip('\n'))


def add_import(test, *imports):
    IMPORTS.setdefault(test, []).extend(imports)


def rewrite(test, name, body):
    """Replaces the body of the test with a manual port (the body is dedented and reindented)."""
    REWRITTEN.setdefault(test, []).append((name, body))


def skip_string(src, i):
    """Returns the index after the string/char literal or comment starting at i, or None."""
    if src.startswith('"""', i):
        j = i + 3
        while not src.startswith('"""', j) or src[j - 1] == '\\':
            j += 1
        return j + 3
    c = src[i]
    if c in '"\'':
        j = i + 1
        while src[j] != c:
            j += 2 if src[j] == '\\' else 1
        return j + 1
    if src.startswith('//', i):
        return src.index('\n', i)
    if src.startswith('/*', i):
        return src.index('*/', i) + 2
    return None


def block_end(src, start):
    """Returns the index after the closing brace matching the opening brace at start."""
    depth = 0
    i = start
    while True:
        j = skip_string(src, i)
        if j is not None:
            i = j
            continue
        if src[i] == '{':
            depth += 1
        elif src[i] == '}':
            depth -= 1
            if depth == 0:
                return i + 1
        i += 1


def find_test(src, name):
    """Returns the start of the annotation line, the indentation and the boundaries of the body of the test."""
    marker = '@DisplayName(%s)' % java_string(name)
    idx = src.find(marker)
    if idx < 0:
        raise SystemExit('test not found: %s' % name)
    line_start = src.rindex('\n', 0, idx) + 1
    indent = src[line_start:idx]
    body_start = src.index('{', src.index(')', idx + len(marker)))
    return line_start, indent, body_start, block_end(src, body_start)


def disable_test(src, name, reason):
    line_start, indent, body_start, body_end = find_test(src, name)
    src = src[:body_start] + '{\n' + indent + '}' + src[body_end:]
    prev_start = src.rindex('\n', 0, line_start - 1) + 1
    if src[prev_start:line_start].strip().startswith('@Disabled('):
        # replace the existing reason (e.g., JRuby only)
        return src[:prev_start] + indent + '@Disabled(%s)\n' % java_string(reason) + src[line_start:]
    return src[:line_start] + indent + '@Disabled(%s)\n' % java_string(reason) + src[line_start:]


def disable_context(test, reason, *names):
    DISABLED_CONTEXTS.setdefault(test, []).extend((name, reason) for name in names)


def disable_nested_class(src, name, reason):
    marker = '@DisplayName(%s)' % java_string(name)
    idx = src.find(marker)
    if idx < 0 or not src[:idx].rstrip().endswith('@Nested'):
        raise SystemExit('context not found: %s' % name)
    line_start = src.rindex('\n', 0, idx) + 1
    indent = src[line_start:idx]
    body_start = src.index('{', idx)
    body_end = block_end(src, body_start)
    src = src[:body_start] + '{\n' + indent + '}' + src[body_end:]
    return src[:line_start] + indent + '@Disabled(%s)\n' % java_string(reason) + src[line_start:]


def rewrite_test(src, name, body):
    _, indent, body_start, body_end = find_test(src, name)
    body = textwrap.dedent(body).strip('\n')
    body = '\n'.join((indent + '    ' + line) if line else '' for line in body.split('\n'))
    return src[:body_start] + '{\n' + body + '\n' + indent + '}' + src[body_end:]


def java_string(value):
    return '"' + value.replace('\\', '\\\\').replace('"', '\\"') + '"'


def fix(test):
    path = test_dir(test) / (test + '.java')
    src = path.read_text()
    for name, reason in DISABLED_CONTEXTS.get(test, []):
        src = disable_nested_class(src, name, reason)
    for name, reason in DISABLED.get(test, []):
        src = disable_test(src, name, reason)
    for name, body in REWRITTEN.get(test, []):
        src = rewrite_test(src, name, body)
    for old, new in COMMON_REPLACEMENTS:
        src = old.sub(new, src) if isinstance(old, re.Pattern) else src.replace(old, new)
    for old, new in REPLACEMENTS.get(test, []):
        if isinstance(old, re.Pattern):
            src, count = old.subn(new, src)
        else:
            count = src.count(old)
            src = src.replace(old, new)
        if count == 0:
            print('warning: %s: no match for %r' % (test, old), file=sys.stderr)
    if MEMBERS.get(test):
        members = '\n\n'.join('\n'.join(('    ' + line) if line else '' for line in m.split('\n'))
                                for m in MEMBERS[test])
        end = src.rstrip().rindex('}')
        src = src[:end].rstrip('\n') + '\n\n' + members + '\n' + src[end:]
    for imp in IMPORTS.get(test, []):
        line = 'import %s;' % imp
        if line not in src:
            anchor = 'import static org.junit.jupiter.api.Assertions.*;' if imp.startswith('static ') else 'import java.util.*;'
            src = src.replace(anchor, anchor + '\n' + line, 1)
    if (DISABLED.get(test) or DISABLED_CONTEXTS.get(test)) and 'import org.junit.jupiter.api.Disabled;' not in src:
        src = src.replace('import org.junit.jupiter.api.DisplayName;',
                          'import org.junit.jupiter.api.Disabled;\nimport org.junit.jupiter.api.DisplayName;', 1)
    path.write_text(src)


