def anonymous_document(m):
    opts = m.group(1) or 'new LinkedHashMap<>()'
    indent = m.group(2)
    return ('var doc = new Document(new ArrayList<String>(), %s) {\n' % opts
            + indent + '    @Override\n'
            + indent + '    public String applySubs(String text) {\n'
            + indent + '        throw new AssertionError("apply_subs should not be called");\n'
            + indent + '    }\n'
            + indent + '};')


replace('AttributeListTest',
        re.compile(r'var doc = emptyDocument\((.*)\);\n(\s+)/\* FIXME DEFS \*/ "def doc\.apply_subs[^\n]*";'),
        anonymous_document)

